on, bl, co = SV['on Terrebonne'], SV['within one block'], SV['corridor (both)']; tp = E['thu_pm']; T71 = E['stated']['table71']
pc = lambda x: f'{100 * x:.0f}\\,\\%'; ci = lambda c: f'{100 * c[0]:.0f}--{100 * c[1]:.0f}\\,\\%'
per_rows = '\n'.join(f"{r['label']} & {r['terrebonne_occupied']} & {r['terrebonne_vacant']} & {pc(r['terrebonne_occupancy'])} & {r['stubs_occupied']} & {r['stubs_vacant']} & {pc(r['stubs_occupancy'])} \\\\" for r in E['by_period'])
sec_rows = '\n'.join(f"{s} & {v['blocks']} & {v['exp_supply_derived']} & {v['exp_thu_pm_occupied']} & {v['lidar_night']} & {pc(v['lidar_night_over_exp_supply'])} & {v['optical_day']} \\\\" for s, v in CU['by_sector'].items())
sv_rows = '\n'.join(f"{esc(k)} & {g['respondents']} & {g['with_vehicle']} & {g['offstreet_built_ge1']} of {g['offstreet_built_answered']} & {g['parked_own_offstreet']} & {g['parked_terrebonne']} & {g['parked_cross_within_block']} & {g['street_parkers']} & {g['hardship_strict']} / {g['hardship_loose']} \\\\" for k, g in SV.items())
win_rows = '\n'.join(f"{w['winter']} & {w['loading_borough']} & {w['loading_sector']} & {w['storm_to_loading_borough']} & {w['storm_to_loading_sector']} & {w['snow_days']} \\\\" for w in WN['rows'])
